import sys

def translate_sentence(S, M):
    lower_map = {b: a for a, b in zip(M, 'abcdefghijklmnopqrstuvwxyz')}
    upper_map = {b.upper(): a.upper() for a, b in zip(M, 'abcdefghijklmnopqrstuvwxyz')}
    translation_map = {**lower_map, **upper_map, '_': ' '}
    return ''.join(translation_map.get(c, c) for c in S)

def main():
    import sys
    input = sys.stdin.read().splitlines()
    T, M = input[0].split()
    T = int(T)
    sentences = input[1:T+1]
    for S in sentences:
        print(translate_sentence(S, M))

main()
